/**
 * Test class for {@link Options#addOptions(Options)} method.
 */
public class AddOptionsTests {

    @Test
    public void testAddOptionsAddsSimpleOptions() {
        Options target = new Options();
        Options source = new Options();

        Option optA = new Option("a", "alpha", true, "alpha option");
        Option optB = new Option("b", "bravo", false, "bravo option");

        source.addOption(optA);
        source.addOption(optB);

        Options result = target.addOptions(source);

        assertSame("addOptions should return this instance", target, result);
        assertTrue("Target should contain option 'a'", target.hasOption("a"));
        assertTrue("Target should contain option 'b'", target.hasOption("b"));
        assertTrue("Target should contain long option 'alpha'", target.hasOption("alpha"));
        assertTrue("Target should contain long option 'bravo'", target.hasOption("bravo"));

        // Verify the options are the same instances
        assertSame("Option 'a' should be same instance", optA, target.getOption("a"));
        assertSame("Option 'b' should be same instance", optB, target.getOption("b"));
    }

    @Test
    public void testAddOptionsAddsRequiredOptions() {
        Options target = new Options();
        Options source = new Options();

        Option requiredOpt = Option.builder("r")
            .longOpt("required")
            .required(true)
            .desc("required option")
            .build();

        source.addOption(requiredOpt);

        target.addOptions(source);

        assertTrue("Target should contain required option 'r'", target.hasOption("r"));
        assertTrue("Option 'r' should be marked as required", target.getOption("r").isRequired());

        // Check required options list
        Collection<?> requiredOptions = target.getRequiredOptions();
        assertEquals("Should have 1 required option", 1, requiredOptions.size());
        assertTrue("Required options should contain 'r'", requiredOptions.contains("r"));
    }

    @Test
    public void testAddOptionsThrowsOnDuplicateKey() {
        Options target = new Options();
        Option existing = new Option("a", "alpha", true, "existing alpha");
        target.addOption(existing);

        Options source = new Options();
        Option duplicate = new Option("a", "alpha-dup", false, "duplicate alpha");
        source.addOption(duplicate);

        try {
            target.addOptions(source);
            fail("Expected IllegalArgumentException due to duplicate key");
        } catch (IllegalArgumentException ex) {
            assertEquals("Duplicate key: a", ex.getMessage());
        }

        // Verify target still has the original option
        assertTrue("Target should still have original option", target.hasOption("a"));
        assertSame("Target should still have original option instance", existing, target.getOption("a"));
    }

    @Test
