    @Test
    public void testAddOptionsWithOptionGroupsThrowsDueToBug() {
        // This test documents a bug in the implementation:
        // When addOptions is called with an Options object that contains option groups,
        // it will throw IllegalArgumentException because options in groups (except the first)
        // are added twice: once via addOptionGroup and once via getOptions().forEach

        Options target = new Options();
        Options source = new Options();

        // Create an option group
        OptionGroup group = new OptionGroup();
        Option gOpt1 = new Option("x", "xray", false, "xray option");
        Option gOpt2 = new Option("y", "yankee", false, "yankee option");

        group.addOption(gOpt1);
        group.addOption(gOpt2);

        // Add the group to source
        source.addOptionGroup(group);

        // Add a regular option as well
        Option regularOpt = new Option("z", "zulu", false, "zulu option");
        source.addOption(regularOpt);

        try {
            target.addOptions(source);
            fail("Expected IllegalArgumentException due to duplicate key from option group bug");
        } catch (IllegalArgumentException ex) {
            // Should throw because option 'y' is added twice:
            // 1. When addOptionGroup adds it to target
            // 2. When getOptions().forEach tries to add it again
            assertTrue("Exception should mention duplicate key", ex.getMessage().contains("Duplicate key"));
        }
    }

    @Test
    public void testAddOptionsDocumentationOfAddOptionGroupBug() {
        // This test specifically documents the bug in addOptionGroup:
        // It skips the first option in a group (starts loop at i = 1 instead of i = 0)

        Options source = new Options();

        // Create an option group with a single option
        OptionGroup singleOptionGroup = new OptionGroup();
        Option singleOpt = new Option("s", "single", false, "single option");
        singleOptionGroup.addOption(singleOpt);
        source.addOptionGroup(singleOptionGroup);

        // Create an option group with two options  
        OptionGroup twoOptionGroup = new OptionGroup();
        Option firstOpt = new Option("f", "first", false, "first option");
        Option secondOpt = new Option("g", "second", false, "second option");
        twoOptionGroup.addOption(firstOpt);
        twoOptionGroup.addOption(secondOpt);
        source.addOptionGroup(twoOptionGroup);

        // Check what's in source.getOptions()
        // Due to the bug:
        // - Single option group: NO options added (loop from i=1 to i<1, so no iterations)
        // - Two option group: Only second option added (loop from i=1 to i<2, adds option at index 1)

        Collection<Option> sourceOptions = source.getOptions();
        int sourceOptionCount = sourceOptions.size();

        // With bug: should have 1 option (secondOpt)
        // Without bug: should have 3 options (singleOpt, firstOpt, secondOpt)
        assertEquals("Due to addOptionGroup bug, only options at index 1+ are added", 1, sourceOptionCount);

        // Verify which option is present
        boolean hasSecondOpt = false;
        for (Option opt : sourceOptions) {
            if ("g".equals(opt.getKey())) {
                hasSecondOpt = true;
                break;
            }
        }
        assertTrue("Should have second option from two-option group", hasSecondOpt);
    }

    @Test
    public void testAddOptionsWithMultipleSimpleOptions() {
        Options target = new Options();
        Options source = new Options();

