        for (char c = 'a'; c <= 'z'; c++) {
            String opt = String.valueOf(c);
            source.addOption(new Option(opt, opt + "-long", false, "Option " + opt));
        }

        target.addOptions(source);

        // Verify all options were added
        for (char c = 'a'; c <= 'z'; c++) {
            String opt = String.valueOf(c);
            assertTrue("Should have option '" + opt + "'", target.hasOption(opt));
            assertTrue("Should have long option '" + opt + "-long'", target.hasOption(opt + "-long"));
        }

        assertEquals("Should have 26 options", 26, target.getOptions().size());
    }

    @Test
    public void testAddOptionsWithMixedOptionTypes() {
        Options target = new Options();
        Options source = new Options();

        // Add various types of options
        source.addOption(new Option("a", false, "simple option"));
        source.addOption(new Option("b", "bravo", true, "option with arg"));
        source.addOption(Option.builder("c")
            .longOpt("charlie")
            .required(true)
            .hasArg()
            .desc("required option with arg")
            .build());
        source.addOption(Option.builder("d")
            .desc("option without short form")
            .build());

        target.addOptions(source);

        // Verify options were added
        assertTrue("Should have option 'a'", target.hasOption("a"));
        assertTrue("Should have option 'b'", target.hasOption("b"));
        assertTrue("Should have option 'c'", target.hasOption("c"));

        // Option 'd' has no short form, so can't check with hasOption("d")
        // But we can check the options collection
        boolean foundD = false;
        for (Option opt : target.getOptions()) {
            if ("d".equals(opt.getOpt())) {
                foundD = true;
                break;
            }
        }
        assertTrue("Should have option with short form 'd'", foundD);
    }
}

